<script setup lang="ts">import {computed,ref} from 'vue';import {Upload,Check} from 'lucide-vue-next';import AppShell from '@/components/zs/AppShell.vue';import PageHeader from '@/components/zs/PageHeader.vue';import Panel from '@/components/zs/Panel.vue';import Tabs from '@/components/zs/Tabs.vue';import Field from '@/components/zs/Field.vue';import ZButton from '@/components/zs/ZButton.vue';import {setPageMeta} from '@/lib/page-meta';setPageMeta('Lead Capture','Create leads manually or prepare a CSV import.');const mode=ref('Manual entry'),step=ref(1),submitted=ref(false),form=ref({first:'',last:'',company:'',title:'',email:'',phone:'',website:'',linkedin:'',industry:'',size:'',source:'Website',owner:'Ayesha Khan',notes:''});const valid=computed(()=>form.value.first&&form.value.last&&form.value.company&&/^\S+@\S+\.\S+$/.test(form.value.email));const headers=['First name','Last name','Company','Email','Phone','Job title'];const mappings=ref<Record<string,string>>(Object.fromEntries(headers.map(x=>[x,x])));</script>
<template><AppShell><PageHeader title="Lead Capture" description="Add one lead or prepare a reviewed CSV import"/><Panel><Tabs v-model="mode" :items="['Manual entry','CSV import']"/><div v-if="mode==='Manual entry'" class="p-5"><div v-if="submitted" class="rounded-md border border-success/30 bg-success/10 p-6 text-center"><Check class="mx-auto size-6 text-success"/><p class="mt-2 text-sm font-semibold text-content">Lead prepared successfully</p><p class="mt-1 text-xs text-content-muted">This preview has not persisted data to a server.</p><ZButton class="mt-4" @click="submitted=false">Add another</ZButton></div><form v-else class="grid gap-4 sm:grid-cols-2 xl:grid-cols-3" @submit.prevent="valid&&(submitted=true)"><Field v-model="form.first" label="First name" required/><Field v-model="form.last" label="Last name" required/><Field v-model="form.company" label="Company" required/><Field v-model="form.title" label="Job title"/><Field v-model="form.email" label="Email" type="email" required/><Field v-model="form.phone" label="Phone"/><Field v-model="form.website" label="Website"/><Field v-model="form.linkedin" label="LinkedIn"/><Field v-model="form.industry" label="Industry"/><Field v-model="form.size" label="Company size"/><label><span class="label-caps">Lead source</span><select v-model="form.source" class="field mt-1.5"><option>Website</option><option>Referral</option><option>Conference</option><option>Partner</option></select></label><label><span class="label-caps">Owner</span><select v-model="form.owner" class="field mt-1.5"><option>Ayesha Khan</option><option>Bilal Ahmed</option><option>Sara Malik</option></select></label><label class="sm:col-span-2 xl:col-span-3"><span class="label-caps">Notes</span><textarea v-model="form.notes" class="field mt-1.5 min-h-24"></textarea></label><div class="sm:col-span-2 xl:col-span-3"><p v-if="!valid" class="mb-2 text-xs text-danger">First name, last name, company and a valid email are required.</p><ZButton type="submit" :disabled="!valid">Create lead</ZButton></div></form></div><div v-else class="p-5"><div class="mb-5 flex flex-wrap gap-2"><span v-for="n in 5" :key="n" :class="['zs-badge',step>=n?'badge-brand':'badge-neutral']">{{n}} {{['Upload','Preview','Map fields','Duplicates','Summary'][n-1]}}</span></div><div v-if="step===1" class="rounded-md border border-dashed border-line-strong p-12 text-center"><Upload class="mx-auto size-7 text-content-muted"/><p class="mt-3 text-sm font-medium text-content">Drop a CSV file here</p><p class="mt-1 text-xs text-content-muted">Preview accepts CSV only; nothing is uploaded.</p><input class="mt-4 text-xs" type="file" accept=".csv" @change="step=2"/></div><div v-else-if="step===2" class="overflow-x-auto"><table class="w-full min-w-[700px]"><thead><tr class="table-head"><th v-for="x in headers" :key="x" class="px-3 py-2 text-left">{{x}}</th></tr></thead><tbody><tr v-for="n in 3" :key="n" class="table-row-zs"><td class="px-3">{{['Hira','Omar','Maham'][n-1]}}</td><td>Iqbal</td><td>Nexa Retail</td><td>lead@example.pk</td><td>+92 300 1234567</td><td>CFO</td></tr></tbody></table></div><div v-else-if="step===3" class="grid gap-3 sm:grid-cols-2"><label v-for="x in headers" :key="x"><span class="label-caps">CSV: {{x}}</span><select v-model="mappings[x]" class="field mt-1.5"><option v-for="f in headers" :key="f">{{f}}</option><option>Do not import</option></select></label></div><div v-else-if="step===4" class="space-y-3"><div v-for="name in ['Hira Iqbal','Omar Shah']" :key="name" class="rounded-md border border-warning/30 bg-warning/10 p-4"><p class="text-sm font-semibold text-content">Possible duplicate: {{name}}</p><p class="mt-1 text-xs text-content-muted">Email matches an existing CRM contact.</p><div class="mt-3 flex gap-3 text-xs"><label><input type="radio" :name="name" checked/> Skip</label><label><input type="radio" :name="name"/> Update existing</label><label><input type="radio" :name="name"/> Import anyway</label></div></div></div><div v-else class="rounded-md bg-surface-sunken p-8 text-center"><Check class="mx-auto size-7 text-success"/><p class="mt-2 text-sm font-semibold text-content">Import review complete</p><p class="mt-1 text-xs text-content-muted">18 valid rows · 2 duplicates skipped · 0 errors. No data was persisted.</p></div><div class="mt-5 flex justify-between"><ZButton variant="outline" :disabled="step===1" @click="step--">Back</ZButton><ZButton v-if="step<5" :disabled="step===1" @click="step++">Continue</ZButton></div></div></Panel></AppShell></template>
